, ["103", "park", "0", "300"], ["104", "choi", "0", "250"], ["105", "kim", "30", "300"]], "type": "table", "columns": ["EMP_NO", "NAME_FUNC", "BONUS_N", "PAY_SUM"]}], "answer": 4, "explanation": "④은 LOWER(EMP_NAME)이 이름을 소문자로 바꾸고, COALESCE(BONUS, 0)이 BONUS가 NULL인 102, 104행에서 0을 반환하므로 PAY_SUM이 각각 280, 250으로 계산된다. 따라서 101행은 kim, 50, 350이고 103행은 park, 0, 300이며 105행은 kim, 30, 300으로 나온다. ①은 PAY_SUM에서 COALESCE를 빼고 SAL + BONUS로 계산하는 경우이므로 BONUS가 NULL인 행의 PAY_SUM이 NULL이 되어 틀리다. ②는 COALESCE(BONUS, SAL)처럼 NULL 보너스를 급여로 대체하여 102행 BONUS_N이 280, 104행 BONUS_N이 250으로 표시되므로 틀리다. ③은 LOWER가 아니라 UPPER를 적용해 NAME_FUNC가 KIM, LEE처럼 대문자로 나오므로 틀리다. 이 문제의 핵심은 단일행 함수가 각 행마다 적용되고, 산술식에서 NULL은 COALESCE 등으로 대체하지 않으면 NULL 결과를 만들 수 있다는 점이다.", "hidden": {"distractor_sqls": ["SELECT EMP_NO AS \"EMP_NO\",\n       LOWER(EMP_NAME) AS \"NAME_FUNC\",\n       COALESCE(BONUS, 0) AS \"BONUS_N\",\n       SAL + BONUS AS \"PAY_SUM\"\nFROM STAFF\nORDER BY EMP_NO;", "SELECT EMP_NO AS \"EMP_NO\",\n       LOWER(EMP_NAME) AS \"NAME_FUNC\",\n       COALESCE(BONUS, SAL) AS \"BONUS_N\",\n       SAL + COALESCE(BONUS, 0) AS \"PAY_SUM\"\nFROM STAFF\nORDER BY EMP_NO;", "SELECT EMP_NO AS \"EMP_NO\",\n       UPPER(EMP_NAME) AS \"NAME_FUNC\",\n       COALESCE(BONUS, 0) AS \"BONUS_N\",\n       SAL + COALESCE(BONUS, 0) AS \"PAY_SUM\"\nFROM STAFF\nORDER BY EMP_NO;"]}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1562, "completion_tokens": 2206}]}], "verification_log": [{"step": "S6_solve", "answer": 4, "issues": [], "ambiguous": false}, {"ok": true, "step": "verify", "attempt": 1, "reasons": []}], "usage": {"calls": 1, "model": "gpt-5.5", "prompt_tokens": 1562, "completion_tokens": 2206}, "elapsed_sec": 40}, {"origin": "self_generated", "quality_status": "verified", "status": "published", "subject": 2, "area": "SQL 기본", "item": "함수", "kind": "sql_pick", "title": "NULL 포함 금액 계산", "stem": "다음 중 취소되지 않은 주문만 대상으로 주문별 혜택금액을 요구 결과대로 조회하는 SQL로 옳은 것은?", "setup_sql": "CREATE TABLE SHOP_ORDER (\n  ORDER_ID INTEGER,\n  COUPON_AMT INTEGER,\n  POINT_AMT INTEGER,\n  CANCEL_DT DATE\n);\n\nINSERT INTO SHOP_ORDER (ORDER_ID, COUPON_AMT, POINT_AMT, CANCEL_DT) VALUES\n(101, 1000, 500, NULL),\n(102, NULL, 700, NULL),\n(103, 300, NULL, NULL),\n(104, NULL, NULL, NULL),\n(105, 100, 200, DATE '2026-02-10'),\n(106, 0, NULL, NULL);", "query_sql": "", "tables": {"SHOP_ORDER": {"rows": [["101", "1000", "500", null], ["102", null, "700", null], ["103", "300", null, null], ["104", null, null, null], ["105", "100", "200", "2026-02-10"], ["106", "0", null, null]], "columns": ["ORDER_ID", "COUPON_AMT", "POINT_AMT", "CANCEL_DT"]}}, "choices": [{"sql": "SELECT ORDER_ID,\n       COALESCE(COUPON_AMT + POINT_AMT, 0) AS BENEFIT_AMT\nFROM SHOP_ORDER\nWHERE CANCEL_DT IS NULL\nORDER BY ORDER_ID;", "type": "sql"}, {"sql": "SELECT ORDER_ID,\n       COALESCE(COUPON_AMT, 0) + COALESCE(POINT_AMT, 0) AS BENEFIT_AMT\nFROM SHOP_ORDER\nWHERE CANCEL_DT IS NULL\nORDER BY ORDER_ID;", "type": "sql"}, {"sql": "SELECT ORDER_ID,\n       COALESCE(COUPON_AMT, POINT_AMT, 0) AS BENEFIT_AMT\nFROM SHOP_ORDER\nWHERE CANCEL_DT IS NULL\nORDER BY ORDER_ID;", "type": "sql"}, {"sql": "SELECT ORDER_ID,\n       COALESCE(COUPON_AMT, 0) + COALESCE(POINT_AMT, 0) AS BENEFIT_AMT\nFROM SHOP_ORDER\nWHERE CANCEL_DT = NULL\nORDER BY ORDER_ID;", "type": "sql"}], "answer": 2, "explanation": "정답은 ②이다. ②는 COUPON_AMT와 POINT_AMT 각각에 COALESCE를 적용하여 NULL을 0으로 바꾼 뒤 더하므로, 주문 101, 102, 103, 104, 106의 혜택금액이 각각 1500, 700, 300, 0, 0으로 조회된다. ①은 COUPON_AMT + POINT_AMT를 먼저 계산하므로 둘 중 하나라도 NULL이면 덧셈 결과가 NULL이 되고, 이후 COALESCE에 의해 0으로 바뀌어 주문 102와 103의 금액이 잘못된다. ③은 COALESCE(COUPON_AMT, POINT_AMT, 0)로 첫 번째 NULL이 아닌 값만 선택하므로 주문 101의 혜택금액이 1500이 아니라 1000으로 조회된다. ④는 NULL 여부를 CANCEL_DT = NULL로 비교했기 때문에 조건식 결과가 참이 되지 않아 취소되지 않은 주문을 조회하지 못한다. NULL이 섞인 산술식에서는 전체 식에 한 번만 NULL 처리 함수를 적용하는 것과 각 피연산자에 적용하는 것의 결과가 다를 수 있다.", "hidden": {"mode": "match", "requirement": "CANCEL_DT가 NULL인 주문만 조회한다. 혜택금액은 COUPON_AMT와 POINT_AMT를 더한 값으로 하되, 두 금액 중 하나가 NULL이면 0으로 바꾸어 계산하고 둘 다 NULL이면 0으로 표시한다. 결과는 ORDER_ID 오름차순으로 정렬한다.", "reference_sql": "SELECT ORDER_ID,\n       COALESCE(COUPON_AMT, 0) + COALESCE(POINT_AMT, 0) AS BENEFIT_AMT\nFROM SHOP_ORDER\nWHERE CANCEL_DT IS NULL\nORDER BY ORDER_ID;"}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1568, "completion_tokens": 1855}]}], "verification_log": [{"mode": "match", "step": "S4_options", "matches": [false, true, false, false]}, {"step": "S6_solve", "answer": 2, "issues": [], "ambiguous": false}, {"ok": true, "step": "verify", "attempt": 1, "reasons": []}], "usage": {"calls": 1, "model": "gpt-5.5", "prompt_tokens": 1568, "completion_tokens": 1855}, "elapsed_sec": 34}, {"origin": "self_generated", "quality_status": "verified", "status": "published", "subject": 2, "area": "SQL 기본", "item": "WHERE 절", "kind": "result", "title": "WHERE 조건의 행 선택", "stem": "다음 SQL의 실행 결과로 옳은 것은?", "setup_sql": "CREATE TABLE STORE_ITEM (\n  ITEM_ID INTEGER,\n  CATEGORY VARCHAR(10),\n  PRICE INTEGER\n);\n\nINSERT INTO STORE_ITEM (ITEM_ID, CATEGORY, PRICE) VALUES\n(1, 'A', 120),\n(2, 'A', 90),\n(3, 'B', 150),\n(4, 'A', NULL),\n(5, 'A', 120),\n(6, NULL, 130);", "query_sql": "SELECT ITEM_ID, CATEGORY, PRICE\nFROM STORE_ITEM\nWHERE CATEGORY = 'A'\n  AND PRICE >= 100\nORDER BY ITEM_ID;", "tables": {"STORE_ITEM": {"rows": [["1", "A", "120"], ["2", "A", "90"], ["3", "B", "150"], ["4", "A", null], ["5", "A", "120"], ["6", null, "130"]], "columns": ["ITEM_ID", "CATEGORY", "PRICE"]}}, "choices": [{"rows": [["1", "A", "120"], ["2", "A", "90"], ["3", "B", "150"], ["4", "A", null], ["5", "A", "120"], ["6", null, "130"]], "type": "table", "columns": ["ITEM_ID", "CATEGORY", "PRICE"]}, {"rows": [["1", "A", "120"], ["5", "A", "120"]], "type": "table", "columns": ["ITEM_ID", "CATEGORY", "PRICE"]}, {"rows": [["1", "A", "120"], ["4", "A", null], ["5", "A", "120"]], "type": "table", "columns": ["ITEM_ID", "CATEGORY", "PRICE"]}, {"rows": [["2", "A", "90"]], "type": "table", "columns": ["ITEM_ID", "CATEGORY", "PRICE"]}], "answer": 2, "explanation": "② WHERE 절은 각 행에 대해 조건식의 결과가 TRUE인 행만 선택하므로 CATEGORY가 'A'이고 PRICE가 100 이상인 ITEM_ID 1, 5만 조회된다. ITEM_ID 4는 CATEGORY가 'A'이지만 PRICE가 NULL이므로 PRICE >= 100의 결과가 UNKNOWN이 되어 선택되지 않는다. ①은 AND를 OR로 잘못 적용한 결과로, 두 조건 중 하나만 만족해도 행이 선택되어 ITEM_ID 1, 2, 3, 4, 5, 6이 조회된다. ③는 NULL 가격까지 포함하도록 조건을 바꾼 결과이므로 ITEM_ID 1, 4, 5가 조회되어 원래 SQL과 다르다. ④은 PRICE 조건의 비교 방향을 반대로 적용한 결과로, CATEGORY가 'A'이면서 PRICE가 100 이하인 ITEM_ID 2만 조회된다.", "hidden": {"distractor_sqls": ["SELECT ITEM_ID, CATEGORY, PRICE\nFROM STORE_ITEM\nWHERE CATEGORY = 'A'\n  OR PRICE >= 100\nORDER BY ITEM_ID;", "SELECT ITEM_ID, CATEGORY, PRICE\nFROM STORE_ITEM\nWHERE CATEGORY = 'A'\n  AND (PRICE >= 100 OR PRICE IS NULL)\nORDER BY ITEM_ID;", "SELECT ITEM_ID, CATEGORY, PRICE\nFROM STORE_ITEM\nWHERE CATEGORY = 'A'\n  AND PRICE <= 100\nORDER BY ITEM_ID;"]}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1562, "completion_tokens": 1033}]}], "verification_log": [{"step": "S6_solve", "answer": 2, "issues": [], "ambiguous": false}, {"ok": true, "step": "verify", "attempt": 1, "reasons": []}], "usage": {"calls": 1, "model": "gpt-5.5", "prompt_tokens": 1562, "completion_tokens": 1033}, "elapsed_sec": 27}, {"origin": "self_generated", "quality_status": "verified", "status": "published", "subject": 2, "area": "SQL 기본", "item": "WHERE 절", "kind": "sql_pick", "title": "NULL 포함 미취소 조회", "stem": "다음 예약 데이터에서 취소 여부가 'Y'가 아닌 예약을 조회하되, 취소 여부가 NULL인 예약은 미취소로 보아 포함하려고 한다. 결과로 RES_ID, MEMBER_ID를 RES_ID 오름차순으로 반환하는 SQL로 옳은 것은?", "setup_sql": "CREATE TABLE ROOM_BOOKING (\n  RES_ID INTEGER PRIMARY KEY,\n  MEMBER_ID VARCHAR(10) NOT NULL,\n  ROOM_CD VARCHAR(5) NOT NULL,\n  CANCEL_YN CHAR(1)\n);\n\nINSERT INTO ROOM_BOOKING (RES_ID, MEMBER_ID, ROOM_CD, CANCEL_YN) VALUES\n(1, 'M01', 'A', NULL),\n(2, 'M02', 'A', 'Y'),\n(3, 'M03', 'B', 'N'),\n(4, 'M04', 'B', NULL),\n(5, 'M05', 'C', 'H'),\n(6, 'M06', 'C', 'N');", "query_sql": "", "tables": {"ROOM_BOOKING": {"rows": [["1", "M01", "A", null], ["2", "M02", "A", "Y"], ["3", "M03", "B", "N"], ["4", "M04", "B", null], ["5", "M05", "C", "H"], ["6", "M06", "C", "N"]], "columns": ["RES_ID", "MEMBER_ID", "ROOM_CD", "CANCEL_YN"]}}, "choices": [{"sql": "SELECT RES_ID, MEMBER_ID\nFROM ROOM_BOOKING\nWHERE CANCEL_YN <> 'Y'\nORDER BY RES_ID;", "type": "sql"}, {"sql": "SELECT RES_ID, MEMBER_ID\nFROM ROOM_BOOKING\nWHERE CANCEL_YN <> 'Y'\n   OR CANCEL_YN IS NULL\nORDER BY RES_ID;", "type": "sql"}, {"sql": "SELECT RES_ID, MEMBER_ID\nFROM ROOM_BOOKING\nWHERE CANCEL_YN IS NOT NULL\nORDER BY RES_ID;", "type": "sql"}, {"sql": "SELECT RES_ID, MEMBER_ID\nFROM ROOM_BOOKING\nWHERE CANCEL_YN IN ('N', NULL)\nORDER BY RES_ID;", "type": "sql"}], "answer": 2, "explanation": "정답은 ②이다. CANCEL_YN이 'Y'가 아닌 값뿐만 아니라 NULL도 포함해야 하므로, `CANCEL_YN <> 'Y' OR CANCEL_YN IS NULL`처럼 NULL 조건을 별도로 작성해야 하며 결과는 RES_ID 1, 3, 4, 5, 6이다. ①은 `CANCEL_YN <> 'Y'` 조건에서 CANCEL_YN이 NULL인 행의 비교 결과가 UNKNOWN이 되어 제외되므로 RES_ID 1, 4가 빠진다. ③은 NULL이 아닌 행을 모두 선택하므로 취소된 예약인 RES_ID 2까지 포함하고, NULL인 RES_ID 1, 4는 제외한다. ④는 `IN ('N', NULL)`로 NULL을 비교하려 하지만 `= NULL` 비교는 참이 되지 않으므로 NULL 행이 포함되지 않고, 'H' 값인 RES_ID 5도 제외된다.", "hidden": {"mode": "match", "requirement": "취소 여부(CANCEL_YN)가 'Y'가 아닌 예약을 조회하되, CANCEL_YN이 NULL인 예약도 미취소로 보아 포함한다. RES_ID, MEMBER_ID를 조회하고 RES_ID 오름차순으로 정렬한다.", "reference_sql": "SELECT RES_ID, MEMBER_ID\nFROM ROOM_BOOKING\nWHERE CANCEL_YN <> 'Y'\n   OR CANCEL_YN IS NULL\nORDER BY RES_ID;"}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1568, "completion_tokens": 2243}]}], "verification_log": [{"mode": "match", "step": "S4_options", "matches": [false, true, false, false]}, {"step": "S6_solve", "answer": 2, "issues": [], "ambiguous": false}, {"ok": true, "step": "verify", "atte