, 4이며, IN 조건에서 중복은 결과에 영향을 주지 않는다. 따라서 ITEM_ID가 2 또는 4가 아닌 ITEM 행이 선택되어 결과는 (1, PEN), (3, CUP), (5, LAMP), (6, BAG)이다. ①은 서브쿼리 결과에 NULL이 포함되므로 NOT IN 비교가 UNKNOWN이 되어 조건을 만족하는 행이 없어지는 경우를 반영한 결과라서 틀리다. ②는 NOT IN을 IN으로 잘못 해석한 결과로, 중지 대상인 (2, NOTE), (4, TAPE)만 반환되므로 틀리다. ③은 서브쿼리에서 'STOP'이 아닌 사유를 찾도록 조건을 바꾼 결과로, WARN인 ITEM_ID 3만 제외되어 (1, PEN), (2, NOTE), (4, TAPE), (5, LAMP), (6, BAG)이 반환되므로 틀리다.", "hidden": {"distractor_sqls": ["SELECT I.ITEM_ID, I.ITEM_NAME\nFROM ITEM I\nWHERE I.ITEM_ID NOT IN (\n  SELECT H.ITEM_ID\n  FROM HOLD H\n  WHERE H.REASON = 'STOP'\n)\nORDER BY I.ITEM_ID;", "SELECT I.ITEM_ID, I.ITEM_NAME\nFROM ITEM I\nWHERE I.ITEM_ID IN (\n  SELECT H.ITEM_ID\n  FROM HOLD H\n  WHERE H.REASON = 'STOP'\n    AND H.ITEM_ID IS NOT NULL\n)\nORDER BY I.ITEM_ID;", "SELECT I.ITEM_ID, I.ITEM_NAME\nFROM ITEM I\nWHERE I.ITEM_ID NOT IN (\n  SELECT H.ITEM_ID\n  FROM HOLD H\n  WHERE H.REASON <> 'STOP'\n    AND H.ITEM_ID IS NOT NULL\n)\nORDER BY I.ITEM_ID;"]}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1566, "completion_tokens": 2699}]}], "verification_log": [{"step": "S6_solve", "answer": 4, "issues": [], "ambiguous": false}, {"ok": true, "step": "verify", "attempt": 1, "reasons": []}], "usage": {"calls": 1, "model": "gpt-5.5", "prompt_tokens": 1566, "completion_tokens": 2699}, "elapsed_sec": 49}, {"origin": "self_generated", "quality_status": "verified", "status": "published", "subject": 2, "area": "SQL 기본", "item": "GROUP BY·HAVING 절", "kind": "result", "title": "GROUP BY와 HAVING 결과", "stem": "다음 SQL의 실행 결과로 옳은 것은?", "setup_sql": "CREATE TABLE DAILY_SALES (\n  SALE_ID INTEGER PRIMARY KEY,\n  REGION VARCHAR(10),\n  AMT INTEGER\n);\n\nINSERT INTO DAILY_SALES (SALE_ID, REGION, AMT) VALUES\n(1, 'EAST', 100),\n(2, 'EAST', 250),\n(3, 'EAST', NULL),\n(4, 'WEST', 200),\n(5, 'WEST', 50),\n(6, 'NORTH', 300),\n(7, NULL, 120),\n(8, NULL, 190);", "query_sql": "SELECT REGION, COUNT(*) AS SALE_CNT, SUM(AMT) AS TOTAL_AMT\nFROM DAILY_SALES\nGROUP BY REGION\nHAVING SUM(AMT) >= 300\nORDER BY REGION NULLS LAST;", "tables": {"DAILY_SALES": {"rows": [["1", "EAST", "100"], ["2", "EAST", "250"], ["3", "EAST", null], ["4", "WEST", "200"], ["5", "WEST", "50"], ["6", "NORTH", "300"], ["7", null, "120"], ["8", null, "190"]], "columns": ["SALE_ID", "REGION", "AMT"]}}, "choices": [{"rows": [["EAST", "3", "350"], ["WEST", "2", "250"], [null, "2", "310"]], "type": "table", "columns": ["REGION", "SALE_CNT", "TOTAL_AMT"]}, {"rows": [["EAST", "3", "350"], ["NORTH", "1", "300"], [null, "2", "310"]], "type": "table", "columns": ["REGION", "SALE_CNT", "TOTAL_AMT"]}, {"rows": [["EAST", "2", "350"], ["NORTH", "1", "300"], [null, "2", "310"]], "type": "table", "columns": ["REGION", "SALE_CNT", "TOTAL_AMT"]}, {"rows": [["EAST", "3", "350"], [null, "2", "310"]], "type": "table", "columns": ["REGION", "SALE_CNT", "TOTAL_AMT"]}], "answer": 2, "explanation": "GROUP BY REGION은 REGION 값이 같은 행을 하나의 그룹으로 묶으며, NULL인 REGION도 하나의 그룹으로 묶인다. ②에서 그룹별 합계는 EAST 350, WEST 250, NORTH 300, NULL 310이고 HAVING SUM(AMT) >= 300 조건을 만족하는 그룹은 EAST, NORTH, NULL이다. 따라서 결과는 정렬 순서에 따라 EAST의 SALE_CNT 3·TOTAL_AMT 350, NORTH의 SALE_CNT 1·TOTAL_AMT 300, NULL의 SALE_CNT 2·TOTAL_AMT 310이 된다. ①은 HAVING 조건을 COUNT(*) >= 2로 판단한 결과이므로 합계가 250인 WEST가 포함되고, 건수가 1인 NORTH가 제외되어 틀리다. ③는 COUNT(*) 대신 COUNT(AMT)를 사용한 결과로, AMT가 NULL인 EAST 행을 세지 않아 EAST의 SALE_CNT가 2가 되므로 틀리다. ④은 HAVING 조건을 SUM(AMT) > 300으로 판단한 결과라 합계가 정확히 300인 NORTH가 제외되어 틀리다.", "hidden": {"distractor_sqls": ["SELECT REGION, COUNT(*) AS SALE_CNT, SUM(AMT) AS TOTAL_AMT\nFROM DAILY_SALES\nGROUP BY REGION\nHAVING COUNT(*) >= 2\nORDER BY REGION NULLS LAST;", "SELECT REGION, COUNT(AMT) AS SALE_CNT, SUM(AMT) AS TOTAL_AMT\nFROM DAILY_SALES\nGROUP BY REGION\nHAVING SUM(AMT) >= 300\nORDER BY REGION NULLS LAST;", "SELECT REGION, COUNT(*) AS SALE_CNT, SUM(AMT) AS TOTAL_AMT\nFROM DAILY_SALES\nGROUP BY REGION\nHAVING SUM(AMT) > 300\nORDER BY REGION NULLS LAST;"]}, "generati