y", "attempt": 1, "reasons": []}], "usage": {"calls": 1, "model": "gpt-5.5", "prompt_tokens": 1567, "completion_tokens": 2676}, "elapsed_sec": 46}, {"origin": "self_generated", "quality_status": "verified", "status": "published", "subject": 2, "area": "SQL 기본", "item": "조인", "kind": "result", "title": "외부 조인 조건의 위치", "stem": "다음 SQL의 실행 결과로 옳은 것은?", "setup_sql": "CREATE TABLE CUSTOMER (\n  CUST_ID INTEGER,\n  CUST_NAME VARCHAR(20),\n  GRADE VARCHAR(1)\n);\n\nCREATE TABLE ORDER_LOG (\n  ORDER_ID INTEGER,\n  CUST_ID INTEGER,\n  STATUS VARCHAR(10),\n  AMT INTEGER\n);\n\nINSERT INTO CUSTOMER (CUST_ID, CUST_NAME, GRADE) VALUES\n  (1, 'ARI', 'A'),\n  (2, 'BO', 'A'),\n  (3, 'CO', 'B'),\n  (4, 'DI', 'A'),\n  (5, 'EL', NULL);\n\nINSERT INTO ORDER_LOG (ORDER_ID, CUST_ID, STATUS, AMT) VALUES\n  (101, 1, 'PAID', 30),\n  (102, 1, 'CANCEL', 20),\n  (103, 2, 'WAIT', 25),\n  (104, 3, 'PAID', 40),\n  (105, 5, NULL, 10),\n  (106, NULL, 'PAID', 50),\n  (107, 2, 'PAID', 15),\n  (108, 4, 'CANCEL', 60);", "query_sql": "SELECT C.CUST_ID, C.CUST_NAME, O.ORDER_ID, O.STATUS\nFROM CUSTOMER C\nLEFT JOIN ORDER_LOG O\n  ON C.CUST_ID = O.CUST_ID\n AND O.STATUS = 'PAID'\nWHERE C.GRADE = 'A'\nORDER BY C.CUST_ID, O.ORDER_ID;", "tables": {"CUSTOMER": {"rows": [["1", "ARI", "A"], ["2", "BO", "A"], ["3", "CO", "B"], ["4", "DI", "A"], ["5", "EL", null]], "columns": ["CUST_ID", "CUST_NAME", "GRADE"]}, "ORDER_LOG": {"rows": [["101", "1", "PAID", "30"], ["102", "1", "CANCEL", "20"], ["103", "2", "WAIT", "25"], ["104", "3", "PAID", "40"], ["105", "5", null, "10"], ["106", null, "PAID", "50"], ["107", "2", "PAID", "15"], ["108", "4", "CANCEL", "60"]], "columns": ["ORDER_ID", "CUST_ID", "STATUS", "AMT"]}}, "choices": [{"rows": [["1", "ARI", "101", "PAID"], ["2", "BO", "107", "PAID"], ["4", "DI", null, null]], "type": "table", "columns": ["CUST_ID", "CUST_NAME", "ORDER_ID", "STATUS"]}, {"rows": [["1", "ARI", "101", "PAID"], ["2", "BO", "107", "PAID"]], "type": "table", "columns": ["CUST_ID", "CUST_NAME", "ORDER_ID", "STATUS"]}, {"rows": [["1", "ARI", "101", "PAID"], ["2", "BO", "107", "PAID"], ["3", "CO", null, null], ["4", "DI", null, null], ["5", "EL", null, null]], "type": "table", "columns": ["CUST_ID", "CUST_NAME", "ORDER_ID", "STATUS"]}, {"rows": [["1", "ARI", "101", "PAID"], ["1", "ARI", "102", "CANCEL"], ["2", "BO", "103", "WAIT"], ["2", "BO", "107", "PAID"], ["4", "DI", "108", "CANCEL"]], "type": "table", "columns": ["CUST_ID", "CUST_NAME", "ORDER_ID", "STATUS"]}], "answer": 1, "explanation": "①은 CUSTOMER를 보존하는 LEFT OUTER JOIN에서 주문 상태 조건 O.STATUS = 'PAID'를 ON 절에 두었으므로, PAID 주문이 없는 A등급 고객도 NULL 확장 행으로 남는다. 따라서 결과는 (1, ARI, 101, PAID), (2, BO, 107, PAID), (4, DI, NULL, NULL)이다. ②은 O.STATUS = 'PAID'를 WHERE 절에 두어 외부 조인 후 NULL 확장된 행까지 WHERE 조건에서 제거하므로 DI 행이 사라진다. ③는 보존 테이블인 CUSTOMER의 조건 C.GRADE = 'A'를 ON 절로 옮긴 경우로, A등급이 아닌 고객도 고객 행 자체는 보존되어 CO, EL 행이 추가된다. ④은 주문 상태 조건을 생략하여 A등급 고객의 모든 주문이 조인되므로 ARI의 CANCEL 주문, BO의 WAIT 주문, DI의 CANCEL 주문까지 결과에 포함된다.", "hidden": {"distractor_sqls": ["SELECT C.CUST_ID, C.CUST_NAME, O.ORDER_ID, O.STATUS\nFROM CUSTOMER C\nLEFT JOIN ORDER_LOG O\n  ON C.CUST_ID = O.CUST_ID\nWHERE C.GRADE = 'A'\n  AND O.STATUS = 'PAID'\nORDER BY C.CUST_ID, O.ORDER_ID;", "SELECT C.CUST_ID, C.CUST_NAME, O.ORDER_ID, O.STATUS\nFROM CUSTOMER C\nLEFT JOIN ORDER_LOG O\n  ON C.CUST_ID = O.CUST_ID\n AND O.STATUS = 'PAID'\n AND C.GRADE = 'A'\nORDER BY C.CUST_ID, O.ORDER_ID;", "SELECT C.CUST_ID, C.CUST_NAME, O.ORDER_ID, O.STATUS\nFROM CUSTOMER C\nLEFT JOIN ORDER_LOG O\n  ON C.CUST_ID = O.CUST_ID\nWHERE C.GRADE = 'A'\nORDER BY C.CUST_ID, O.ORDER_ID;"]}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1566, "completion_tokens": 2931}]}], "verification_log": [{"step": "S6_solve", "answer": 2, "issues": [], "ambiguous": false}, {"ok": true, "step": "verify", "attempt": 1, "reasons": []}], "usage": {"calls": 1, "model": "gpt-5.5", "prompt_tokens": 1566, "completion_tokens": 2931