, "QTY"]}}, "choices": [{"sql": "SELECT P.PROD_ID, P.PROD_NAME\nFROM PRODUCT P\nWHERE NOT EXISTS (\n  SELECT 1\n  FROM ORDER_ITEM O\n  WHERE O.PROD_ID = P.PROD_ID\n)\nORDER BY P.PROD_ID;", "type": "sql"}, {"sql": "SELECT P.PROD_ID, P.PROD_NAME\nFROM PRODUCT P\nWHERE P.PROD_ID NOT IN (\n  SELECT O.PROD_ID\n  FROM ORDER_ITEM O\n)\nORDER BY P.PROD_ID;", "type": "sql"}, {"sql": "SELECT P.PROD_ID, P.PROD_NAME\nFROM PRODUCT P\nWHERE P.PROD_ID IN (\n  SELECT O.PROD_ID\n  FROM ORDER_ITEM O\n)\nORDER BY P.PROD_ID;", "type": "sql"}, {"sql": "SELECT P.PROD_ID, P.PROD_NAME\nFROM PRODUCT P\nWHERE EXISTS (\n  SELECT 1\n  FROM ORDER_ITEM O\n  WHERE O.PROD_ID IS NULL\n     OR O.PROD_ID <> P.PROD_ID\n)\nORDER BY P.PROD_ID;", "type": "sql"}], "answer": 1, "explanation": "①은 상관 서브쿼리에서 같은 PROD_ID가 존재하지 않는 상품만 선택하므로 요구를 정확히 만족한다. 실제 결과는 (3, 'CAP'), (5, 'BAG'), (6, 'PIN')이다. ②는 NOT IN의 서브쿼리 결과에 NULL이 포함되므로 비교 결과가 UNKNOWN이 되어 주문되지 않은 상품도 반환하지 못한다. ③은 IN을 사용하여 주문 상세에 나타난 상품을 조회하므로 (1, 'PEN'), (2, 'MUG'), (4, 'KEY')가 반환된다. ④는 ORDER_ITEM에 PROD_ID가 NULL인 행이 존재하므로 EXISTS 조건이 모든 PRODUCT 행에 대해 참이 되어 모든 상품을 반환한다.", "hidden": {"mode": "match", "requirement": "ORDER_ITEM의 PROD_ID에 NULL이 포함되어 있어도 이를 주문된 상품으로 보지 않고, ORDER_ITEM에 한 번도 나타나지 않은 PRODUCT의 PROD_ID와 PROD_NAME을 PROD_ID 오름차순으로 조회한다.", "reference_sql": "SELECT P.PROD_ID, P.PROD_NAME\nFROM PRODUCT P\nWHERE NOT EXISTS (\n  SELECT 1\n  FROM ORDER_ITEM O\n  WHERE O.PROD_ID = P.PROD_ID\n)\nORDER BY P.PROD_ID;"}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1572, "completion_tokens": 2373}]}], "verification_log": [{"mode": "match", "step": "S4_options", "matches": [true, false, false, false]}, {"step": "S6_solve", "answer": 1, "issues": [], "ambiguous": false}, {"ok": true, "step": "verify", "attempt": 1, "reasons": []}], "usage": {"calls": 1, "model": "gpt-5.5", "prompt_tokens": 1572, "completion_tokens": 2373}, "elapsed_sec": 47}, {"origin": "self_generated", "quality_status": "verified", "status": "published", "subject": 2, "area": "SQL 활용", "item": "집합 연산자", "kind": "result", "title": "UNION의 중복 제거", "stem": "다음 SQL의 실행 결과로 옳은 것은?", "setup_sql": "CREATE TABLE STORE_A (\n  ITEM_CODE VARCHAR(5)\n);\n\nCREATE TABLE STORE_B (\n  ITEM_CODE VARCHAR(5)\n);\n\nINSERT INTO STORE_A (ITEM_CODE) VALUES\n('A10'),\n('B20'),\n('B20'),\n(NULL);\n\nINSERT INTO STORE_B (ITEM_CODE) VALUES\n('B20'),\n('C30'),\n(NULL),\n('D40');", "query_sql": "SELECT ITEM_CODE\nFROM STORE_A\nUNION\nSELECT ITEM_CODE\nFROM STORE_B\nORDER BY ITEM_CODE NULLS LAST;", "tables": {"STORE_A": {"rows": [["A10"], ["B20"], ["B20"], [null]], "columns": ["ITEM_CODE"]}, "STORE_B": {"rows": [["B20"], ["C30"], ["D40"], [null]], "columns": ["ITEM_CODE"]}}, "choices": [{"rows": [["A10"], ["B20"], ["B20"], ["B20"], ["C30"], ["D40"], [null], [null]], "type": "table", "columns": ["ITEM_CODE"]}, {"rows": [["B20"], [null]], "type": "table", "columns": ["ITEM_CODE"]}, {"rows": [["A10"]], "type": "table", "columns": ["ITEM_CODE"]}, {"rows": [["A10"], ["B20"], ["C30"], ["D40"], [null]], "type": "table", "columns": ["ITEM_CODE"]}], "answer": 4, "explanation": "④ UNION은 두 SELECT 결과를 합친 뒤 중복 행을 제거하므로 ITEM_CODE는 A10, B20, C30, D40, NULL이 한 번씩 출력된다. 이때 집합 연산에서 중복 제거를 판단할 때 NULL도 같은 값처럼 취급되어 NULL 행은 하나만 남는다. ① UNION ALL로 바꾸면 중복을 제거하지 않으므로 B20은 세 번, NULL은 두 번 나타나 결과 행 수가 8행이 된다. ② INTERSECT는 양쪽 결과에 공통으로 존재하는 행만 반환하므로 B20과 NULL만 출력된다. ③ EXCEPT는 앞 SELECT 결과에서 뒤 SELECT 결과에 있는 행을 제외하므로 STORE_A에만 있는 A10만 출력된다.", "hidden": {"distractor_sqls": ["SELECT ITEM_CODE\nFROM STORE_A\nUNION ALL\nSELECT ITEM_CODE\nFROM STORE_B\nORDER BY ITEM_CODE NULLS LAST;", "SELECT ITEM_CODE\nFROM STORE_A\nINTERSECT\nSELECT ITEM_CODE\nFROM STORE_B\nORDER BY ITEM_CODE NULLS LAST;", "SELECT ITEM_CODE\nFROM STORE_A\nEXCEPT\nSELECT ITEM_CODE\nFROM STORE_B\nORDER BY ITEM_CODE NULLS LAST;"]}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1565, "completion_tokens": 1413}]}], "verification_log": [{"step": "S6_solve", "answer": 4, "issues": [], "ambiguous": false}, {"ok": true, "step": "verify", "attempt": 1, "reasons": []}], "usage": {"calls": 1, "model": "gpt-5.5", "prompt_tokens": 1565, "completion_tokens": 1413}, "elapsed_sec": 25}, {"origin": "self_generated", "quality_status": "verified", "status": "published", "subject": 2, "area": "SQL 활용", "item": "집합 연산자", "kind": "sql_pick", "title": "NULL 포함 교집합 조회", "stem": "온라인 반품과 매장 반품에 모두 존재하는 (ITEM_ID, REASON_CD) 조합을 중복 없이 조회하되, REASON_CD가 NULL인 조합도 양쪽 모두 NULL이면 같은 값으로 보아 포함하는 SQL로 옳은 것은?", "setup_sql": "CREATE TABLE ONLINE_RETURN (\n  ITEM_ID VARCHAR(2),\n  REASON_CD VARCHAR(2)\n);\nCREATE TABLE STORE_RETURN (\n  ITEM_ID VARCHAR(2),\n  REASON_CD VARCHAR(2)\n);\nINSERT INTO ONLINE_RETURN (ITEM_ID, REASON_CD) VALUES\n('A', 'R1'),\n('B', NULL),\n('C', NULL),\n('C', NULL),\n('D', 'R2'),\n('E', 'R3'),\n('G', NULL);\nINSERT INTO STORE_RETURN (ITEM_ID, REASON_CD) VALUES\n('A', 'R1'),\n('B', NULL),\n('C', NULL),\n('C', NULL),\n('D', NULL),\n('E', 'R4'),\n('H', 'R5');", "query_sql": "", "tables": {"STORE_RETURN": {"rows": [["A", "R1"], ["B", null], ["C", null], ["C", null], ["D", null], ["E", "R4"], ["H", "R5"]], "columns": ["ITEM_ID", "REASON_CD"]}, "ONLINE_RETURN": {"rows": [["A", "R1"], ["B", null], ["C", null], ["C", null], ["D", "R2"], ["E", "R3"], ["G", null]], "columns": ["ITEM_ID", "REASON_CD"]}}, "choices": [{"sql": "SELECT ITEM_ID, REASON_CD\nFROM ONLINE_RETURN\nINTERSECT ALL\nSELECT ITEM_ID, REASON_CD\nFROM STORE_RETURN\nORDER BY ITEM_ID, REASON_CD NULLS FIRST", "type": "sql"}, {"sql": "SELECT ITEM_ID, REASON_CD\nFROM ONLINE_RETURN\nINTERSECT\nSELECT ITEM_ID, REASON_CD\nFROM STORE_RETURN\nORDER BY ITEM_ID, REASON_CD NULLS FIRST", "type": "sql"}, {"sql": "SELECT DISTINCT O.ITEM_ID, O.REASON_CD\nFROM ONLINE_RETURN O\nJOIN STORE_RETURN S\n  ON O.ITEM_ID = S.ITEM_ID\n AND O.REASON_CD = S.REASON_CD\nORDER BY O.ITEM_ID, O.REASON_CD 