100),\n(4, 'B', 200),\n(5, 'B', NULL),\n(6, 'C', NULL);", "query_sql": "SELECT STORE_CD,\n       COUNT(*) AS ROW_CNT,\n       COUNT(PAY_AMT) AS PAY_CNT,\n       COUNT(DISTINCT PAY_AMT) AS DISTINCT_PAY_CNT,\n       SUM(PAY_AMT) AS SUM_PAY\nFROM SALES_LOG\nGROUP BY STORE_CD\nORDER BY STORE_CD;", "tables": {"SALES_LOG": {"rows": [["1", "A", "100"], ["2", "A", null], ["3", "A", "100"], ["4", "B", "200"], ["5", "B", null], ["6", "C", null]], "columns": ["ORDER_ID", "STORE_CD", "PAY_AMT"]}}, "choices": [{"rows": [["A", "3", "2", "1", "200"], ["B", "2", "1", "1", "200"], ["C", "1", "0", "0", null]], "type": "table", "columns": ["STORE_CD", "ROW_CNT", "PAY_CNT", "DISTINCT_PAY_CNT", "SUM_PAY"]}, {"rows": [["A", "3", "3", "1", "200"], ["B", "2", "2", "1", "200"], ["C", "1", "1", "0", null]], "type": "table", "columns": ["STORE_CD", "ROW_CNT", "PAY_CNT", "DISTINCT_PAY_CNT", "SUM_PAY"]}, {"rows": [["A", "2", "2", "1", "200"], ["B", "1", "1", "1", "200"], ["C", "0", "0", "0", null]], "type": "table", "columns": ["STORE_CD", "ROW_CNT", "PAY_CNT", "DISTINCT_PAY_CNT", "SUM_PAY"]}, {"rows": [["A", "3", "2", "1", "200"], ["B", "2", "1", "1", "200"], ["C", "1", "0", "0", "0"]], "type": "table", "columns": ["STORE_CD", "ROW_CNT", "PAY_CNT", "DISTINCT_PAY_CNT", "SUM_PAY"]}], "answer": 1, "explanation": "① 그룹 함수에서 COUNT(*)는 NULL 포함 행 수를 세고, COUNT(PAY_AMT)는 PAY_AMT가 NULL이 아닌 행만 센다. 따라서 STORE_CD A는 ROW_CNT 3, PAY_CNT 2, DISTINCT_PAY_CNT 1, SUM_PAY 200이고, B는 2, 1, 1, 200이다. C는 PAY_AMT가 모두 NULL이므로 ROW_CNT는 1이지만 PAY_CNT와 DISTINCT_PAY_CNT는 0이며 SUM_PAY는 NULL이다. ② COUNT(PAY_AMT)를 COUNT(*)로 잘못 계산하여 PAY_CNT가 NULL 행까지 포함된다. ③ COUNT(*)를 COUNT(PAY_AMT)로 잘못 계산하여 ROW_CNT가 NULL 값을 가진 행을 제외한다. ④ SUM(PAY_AMT)를 COALESCE로 0 처리한 결과라서 모든 값이 NULL인 C의 SUM_PAY가 NULL이 아니라 0으로 나온다.", "hidden": {"distractor_sqls": ["SELECT STORE_CD,\n       COUNT(*) AS ROW_CNT,\n       COUNT(*) AS PAY_CNT,\n       COUNT(DISTINCT PAY_AMT) AS DISTINCT_PAY_CNT,\n       SUM(PAY_AMT) AS SUM_PAY\nFROM SALES_LOG\nGROUP BY STORE_CD\nORDER BY STORE_CD;", "SELECT STORE_CD,\n       COUNT(PAY_AMT) AS ROW_CNT,\n       COUNT(PAY_AMT) AS PAY_CNT,\n       COUNT(DISTINCT PAY_AMT) AS DISTINCT_PAY_CNT,\n       SUM(PAY_AMT) AS SUM_PAY\nFROM SALES_LOG\nGROUP BY STORE_CD\nORDER BY STORE_CD;", "SELECT STORE_CD,\n       COUNT(*) AS ROW_CNT,\n       COUNT(PAY_AMT) AS PAY_CNT,\n       COUNT(DISTINCT PAY_AMT) AS DISTINCT_PAY_CNT,\n       COALESCE(SUM(PAY_AMT), 0) AS SUM_PAY\nFROM SALES_LOG\nGROUP BY STORE_CD\nORDER BY STORE_CD;"]}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1563, "completion_tokens": 1175}]}], "verification_log": [{"step": "S6_solve", "answer": 1, "issues": [], "ambiguous": false}, {"ok": true, "step": "verify", "attempt": 1, "reasons": []}], "usage": {"calls": 1, "model": "gpt-5.5", "prompt_tokens": 1563, "completion_tokens": 1175}, "elapsed_sec": 34}, {"origin": "self_generated", "quality_status": "verified", "status": "published", "subject": 2, "area": "SQL 활용", "item": "그룹 함수", "kind": "sql_pick", "title": "NULL 포함 평균과 건수", "stem": "STUDY_SCORE 테이블에서 팀별 전체 응시자 수, 점수가 입력된 응시자 수, NULL을 제외한 평균 점수를 구하되, 전체 응시자가 2명 이상인 팀만 TEAM_CD 오름차순으로 반환하는 SQL로 옳은 것은?", "setup_sql": "CREATE TABLE STUDY_SCORE (\n  STUDENT_ID INTEGER,\n  TEAM_CD VARCHAR(2),\n  SCORE INTEGER\n);\n\nINSERT INTO STUDY_SCORE (STUDENT_ID, TEAM_CD, SCORE) VALUES\n(1, 'A', 80),\n(2, 'A', NULL),\n(3, 'A', 70),\n(4, 'B', NULL),\n(5, 'B', 90),\n(6, 'C', NULL),\n(7, 'C', NULL),\n(8, 'D', 100);", "query_sql": "", "tables": {"STUDY_SCORE": {"rows": [["1", "A", "80"], ["2", "A", null], ["3", "A", "70"], ["4", "B", null], ["5", "B", "90"], ["6", "C", null], ["7", "C", null], ["8", "D", "100"]], "columns": ["STUDENT_ID", "TEAM_CD", "SCORE"]}}, "choices": [{"sql": "SELECT TEAM_CD,\n       COUNT(SCORE) AS MEMBER_CNT,\n       COUNT(*) AS SCORED_CNT,\n       ROUND(AVG(SCORE), 1) AS AVG_SCORE\nFROM STUDY_SCORE\nGROUP BY TEAM_CD\nHAVING COUNT(SCORE) >= 2\nORDER BY TEAM_CD;", "type": "sql"}, {"sql": "SELECT TEAM_CD,\n       COUNT(*) AS MEMBER_CNT,\n       COUNT(SCORE) AS SCORED_CNT,\n       ROUND(AVG(SCORE), 1) AS AVG_SCORE\nFROM STUDY_SCORE\nGROUP BY TEAM_CD\nHAVING COUNT(*) >= 2\nORDER BY TEAM_CD;", "type": "sql"}, {"sql": "SELECT TEAM_CD,\n       COUNT(*) AS MEMBER_CNT,\n       COUNT(SCORE) AS SCORED_CNT,\n       ROUND(AVG(COALESCE(SCORE, 0)), 1) AS AVG_SCORE\nFROM STUDY_SCORE\nGROUP BY TEAM_CD\nHAVING COUNT(*) >= 2\nORDER BY TEAM_CD;", "type": "sql"}, {"sql": "SELECT TEAM_CD,\n       COUNT(*) AS MEMBER_CNT,\n       COUNT(SCORE) AS SCORED_CNT,\n       ROUND(AVG(SCORE), 1) AS AVG_SCORE\nFROM STUDY_SCORE\nGROUP BY TEAM_CD\nHAVING COUNT(*) >= 2\n   AND COUNT(SCORE) > 0\nORDER BY TEAM_CD;", "type": "sql"}], "answer": 2, "explanation": "정답은 ②이다. COUNT(*)는 SCORE가 NULL인 행도 포함해 전체 응시자 수를 세고, COUNT(SCORE)는 SCORE가 NULL인 행을 제외하므로 A는 3명/2건, B는 2명/1건, C는 2명/0건이 된다. AVG(SCORE)는 NULL을 제외하고 평균을 계산하므로 결과는 A 75.0, B 90.0, C NULL이다. ①은 HAVING에서 COUNT(SCORE) >= 2를 사용해 점수가 입력된 행이 2건 이상인 팀만 남기므로 B와 C가 제외되고, MEMBER_CNT와 SCORED_CNT의 의미도 뒤바뀐다. ③은 COALESCE(SCORE, 0)으로 NULL을 0점처럼 평균에 포함하므로 A 50.0, B 45.0, C 0.0이 되어 요구와 다르다. ④는 COUNT(SCORE) > 0 조건을 추가해 SCORE가 모두 NULL인 C 팀을 제외하므로, 전체 응시자가 2명 이상인 팀을 모두 포함해야 한다는 조건을 만족하지 못한다.", "hidden": {"mode": "match", "requirement": "팀별로 TEAM_CD, 전체 응시자 수(MEMBER_CNT), NULL이 아닌 SCORE 건수(SCORED_CNT), NULL을 제외한 평균 SCORE(AVG_SCORE, 소수 1자리 반올림)를 반환한다. 전체 응시자가 2명 이상인 팀만 포함하고, TEAM_CD 오름차순으로 정렬한다.", "reference_sql": "SELECT TEAM_CD,\n       COUNT(*) AS MEMBER_CNT,\n       COUNT(SCORE) AS SCORED_CNT,\n       ROUND(AVG(SCORE), 1) AS AVG_SCORE\nFROM STUDY_SCORE\nGROUP BY TEAM_CD\nHAVING COUNT(*) >= 2\nORDER BY TEAM_CD;"}, "generation_model": "gpt-5.5", "prompt_version": "p-2026.11.05b", "generation_log": [{"usage": [{"model": "gpt-5.5-2026-04-23", "prompt_tokens": 1569, "completion_tokens": 2439}]}], "verification_log": [{"mode": "match", "step": "S4_options", "matches": [false, true, false, false]}, {"step": "S6_solve"